fn add_script_to_execute_on_document_created(webview: &ICoreWebView2, js: String) -> Result<()> {
  use crate::startup_probe::{begin_script, observe_script, PumpScope, ScriptSignal};
  let ordinal = begin_script();
  let webview = webview.clone();
  // 固定macroのAPI closureを同じBox/FnOnce所有権で消費し、COM cloneをwait前にdropする。
  let start: Box<dyn FnOnce(ICoreWebView2AddScriptToExecuteOnDocumentCreatedCompletedHandler) -> webview2_com::Result<()>> =
    Box::new(move |handler| unsafe {
      let js = HSTRING::from(js);
      observe_script(ordinal, ScriptSignal::ApiStart);
      webview.AddScriptToExecuteOnDocumentCreated(&js, &handler).map_err(Into::into)
    });
  let (tx, rx) = mpsc::channel();
  let completed: Box<dyn FnOnce(windows::core::Result<()>, String) -> windows::core::Result<()>> = Box::new(|e, _| e);
  // create/Invokeのonce-takeと引数変換は元macroを再利用。送信失敗のexpectも維持する。
  let callback = AddScriptToExecuteOnDocumentCreatedCompletedHandler::create(Box::new(move |e, value| {
    observe_script(ordinal, ScriptSignal::Callback(e.is_ok()));
    let result = completed(e, value).map_err(webview2_com::Error::WindowsError);
    tx.send(result).expect("send over mpsc channel");
    observe_script(ordinal, ScriptSignal::Sent);
    Ok(())
  }));
  let api = start(callback);
  observe_script(ordinal, ScriptSignal::ApiReturn);
  let result: webview2_com::Result<()> = api.and_then(|_| {
    crate::startup_pump::wait_with_pump(rx, PumpScope::Script(ordinal))?
  });
  observe_script(ordinal, ScriptSignal::Return(result.is_ok()));
  result.map_err(Into::into)
}

